```java
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());

        Map<String, Integer> frequencies = new HashMap<>();
        for (int i = 0; i < n; i++) {
            String password = br.readLine().trim();
            frequencies.put(password, frequencies.getOrDefault(password, 0) + 1);
        }

        long answer = 0;

        for (Map.Entry<String, Integer> entry : frequencies.entrySet()) {
            String password = entry.getKey();
            int countA = entry.getValue();

            Set<String> substrings = new HashSet<>();
            for (int start = 0; start < password.length(); start++) {
                for (int end = start + 1; end <= password.length(); end++) {
                    substrings.add(password.substring(start, end));
                }
            }

            long matchingUsers = 0;
            for (String substring : substrings) {
                matchingUsers += frequencies.getOrDefault(substring, 0);
            }

            answer += (long) countA * matchingUsers;
        }

        // Remove pairs where a user is paired with themselves.
        answer -= n;

        System.out.println(answer);
    }
}
```

